/* ---- 4. اردو → رومن، ایک لفظ (اعراب سمجھتے ہوئے) ---- */
var VOWEL_LETTERS = { "ا": 1, "آ": 1, "ی": 1, "ے": 1, "و": 1, "ئ": 1, "ۓ": 1 };

